export function walkToward(position,target,speed,seconds,width,height){if(width<=0||height<=0)return {...position,arrived:false};const dx=(target.x-position.x)*width,dy=(target.y-position.y)*height,distance=Math.hypot(dx,dy),travel=Math.min(distance,speed*seconds);if(distance<1)return {...target,arrived:true};return {x:position.x+dx/distance*travel/width,y:position.y+dy/distance*travel/height,arrived:travel===distance};}
export class MonsterPark{
 constructor(world,monsters,{onPet=()=>{}}={}){this.world=world;this.onPet=onPet;this.last=0;this.frame=null;this.stopped=false;this.width=world.clientWidth;this.height=world.clientHeight;this.creatures=monsters.map((m,i)=>({id:m.id,index:m.index,node:world.querySelector(`[data-park-id="${m.id}"]`),position:{x:.15+(i%4)*.23,y:.4+Math.floor(i/4)*.16},target:null,rest:0,speed:22+Math.random()*12}));this.creatures.forEach(c=>{c.target=this.target();c.rest=Math.random()*1.5;});this.resize=new ResizeObserver(entries=>{const r=entries[0].contentRect;this.width=r.width;this.height=r.height;});this.resize.observe(world);this.boundFrame=t=>this.tick(t);this.frame=requestAnimationFrame(this.boundFrame);}
 target(){return {x:.1+Math.random()*.79,y:.36+Math.random()*.45};}
 tick(time){if(this.stopped)return;const dt=this.last?Math.min((time-this.last)/1000,.05):0;this.last=time;if(!document.hidden){for(const c of this.creatures){c.rest-=dt;if(c.rest<=0){const previous=c.position;c.position=walkToward(c.position,c.target,c.speed,dt,this.width,this.height);c.node.classList.toggle('walking',!c.position.arrived);c.node.style.setProperty('--facing',c.position.x<previous.x?'-1':'1');if(c.position.arrived){c.rest=2+Math.random()*4;c.target=this.target();c.node.classList.remove('walking');}}c.node.style.left=c.position.x*100+'%';c.node.style.top=c.position.y*100+'%';c.node.style.zIndex=Math.round(c.position.y*100);c.node.style.setProperty('--depth',String(.74+c.position.y*.34));}}this.frame=requestAnimationFrame(this.boundFrame);}
 gather(){this.creatures.forEach((c,i)=>{const angle=i/Math.max(this.creatures.length,1)*Math.PI*2;c.target={x:.5+Math.cos(angle)*.2,y:.6+Math.sin(angle)*.12};c.rest=0;c.speed=45;});}
 feed(){this.gather();this.world.classList.add('feeding');clearTimeout(this.feedTimer);this.feedTimer=setTimeout(()=>{this.world.classList.remove('feeding');this.creatures.forEach(c=>{c.speed=22+Math.random()*12;});},6000);}
 pet(id){const c=this.creatures.find(c=>c.id===id);if(!c)return;c.rest=3;c.node.classList.remove('walking');c.node.classList.add('happy');clearTimeout(c.happyTimer);c.happyTimer=setTimeout(()=>c.node.classList.remove('happy'),1800);this.onPet(c);}
 destroy(){this.stopped=true;cancelAnimationFrame(this.frame);this.resize.disconnect();clearTimeout(this.feedTimer);this.creatures.forEach(c=>clearTimeout(c.happyTimer));}
}
